<?php
namespace App\Services\Reconciliation\Governance;use App\Enums\BankTransactionStatus;use App\Enums\DocumentStatus;use App\Enums\ReconciliationStatus;use App\Models\BankTransaction;use App\Models\FinancialDocument;use App\Models\Reconciliation;use App\Services\Audit\AuditService;use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
final class ReconciliationApprovalService {public function __construct(private AuditService $audit){} public function approve(Reconciliation $input,string $checkerId,?string $note=null):Reconciliation{return DB::transaction(function()use($input,$checkerId,$note){$r=Reconciliation::query()->with('items')->lockForUpdate()->findOrFail($input->id);if(($r->proposed_by&&$r->proposed_by===$checkerId)&&$r->requires_checker)throw ValidationException::withMessages(['approval'=>'El mismo usuario que propone no puede aprobar.']);if($r->status!==ReconciliationStatus::PendingReview)throw ValidationException::withMessages(['approval'=>'La conciliación no está pendiente de aprobación.']);foreach($r->items as $item){$doc=FinancialDocument::query()->lockForUpdate()->findOrFail($item->financial_document_id);$tx=BankTransaction::query()->lockForUpdate()->findOrFail($item->bank_transaction_id);$open=(float)$doc->open_amount;$apply=(float)$item->applied_amount;if($open+0.0001<$apply)throw ValidationException::withMessages(['approval'=>'El saldo del documento cambió y ya no permite aprobar.']);$remaining=max(0,$open-$apply);$doc->update(['open_amount'=>$remaining,'status'=>$remaining<=0?DocumentStatus::Paid:DocumentStatus::Partial]);$applied=(float)DB::table('reconciliation_items')->join('reconciliations','reconciliations.id','=','reconciliation_items.reconciliation_id')->where('bank_transaction_id',$tx->id)->where('reconciliations.status',ReconciliationStatus::Approved->value)->sum('applied_amount')+$apply;$tx->update(['status'=>$applied+0.0001>=abs((float)$tx->amount)?BankTransactionStatus::Reconciled:BankTransactionStatus::PartiallyReconciled]);}$before=$r->toArray();$r->update(['status'=>ReconciliationStatus::Approved,'approved_by'=>$checkerId,'approved_at'=>now(),'reviewed_by'=>$checkerId,'reviewed_at'=>now(),'review_note'=>$note]);$this->audit->record('reconciliation.approved',$r,$before,$r->fresh()->toArray(),['maker'=>$r->proposed_by,'checker'=>$checkerId]);return $r->fresh();});}
 public function reject(Reconciliation $input,string $checkerId,string $note):Reconciliation{return DB::transaction(function()use($input,$checkerId,$note){$r=Reconciliation::query()->lockForUpdate()->findOrFail($input->id);if($r->proposed_by===$checkerId&&$r->requires_checker)throw ValidationException::withMessages(['approval'=>'El proponente no puede rechazar como checker.']);$before=$r->toArray();$r->update(['status'=>ReconciliationStatus::Rejected,'reviewed_by'=>$checkerId,'reviewed_at'=>now(),'review_note'=>$note]);$this->audit->record('reconciliation.rejected',$r,$before,$r->fresh()->toArray());return $r->fresh();});}}
